"""Validate corpus YAML: pinned revision, license, provenance, variety, and split role.

Evaluation-only sources cannot enter training mixtures."""

from __future__ import annotations

from enum import Enum
from pathlib import Path
from typing import Iterable

import yaml
from pydantic import BaseModel, ConfigDict, Field, field_validator


class Provenance(str, Enum):
    """How the text came to exist."""

    HUMAN = "human"
    """Written or professionally translated by people."""

    SYNTHETIC = "synthetic"
    """Generated by a language model."""

    MACHINE_TRANSLATED = "machine_translated"
    """Human source text, machine-translated into the target language."""

    MINED = "mined"
    """Automatically aligned bitext; alignment quality unverified."""


class Role(str, Enum):
    """What the source is allowed to be used for."""

    TRAIN = "train"
    HELDOUT = "heldout"
    """Held out from training; used for held-out LM loss."""

    EVAL_ONLY = "eval_only"
    """Never enters any mixture, under any configuration."""


class Modality(str, Enum):
    MONOLINGUAL = "monolingual"
    PARALLEL = "parallel"


class CorpusSource(BaseModel):
    """One declared corpus."""

    model_config = ConfigDict(extra="forbid")

    name: str = Field(description="Short stable key, used in mixture configs.")
    hf_id: str | None = Field(
        default=None, description="Hugging Face dataset id, if hosted there."
    )
    hf_config: str | None = Field(default=None, description="Dataset config/subset name.")
    hf_revision: str | None = Field(
        default=None,
        description="Pinned commit SHA. Required for any source with role=train.",
    )
    hf_parquet_revision: str | None = Field(
        default=None,
        description=(
            "Pinned commit SHA on refs/convert/parquet, for script-based datasets "
            "read through the Hub's auto-converted parquet branch. That branch is "
            "mutable — the Hub regenerates it whenever the source changes — so "
            "resolving it by name at load time leaves the source unpinned."
        ),
    )
    hf_split: str = Field(default="train")
    hf_files: list[str] | None = Field(
        default=None,
        description=(
            "Glob patterns inside the pinned repository. When set, the text is read "
            "from a local extraction (akanlm.corpora.extract) and never from the Hub "
            "at load time. Required where the files carry audio next to the text."
        ),
    )
    hf_columns: list[str] | None = Field(
        default=None, description="Columns kept by the extraction; everything else is never downloaded."
    )
    group_by: str | None = Field(
        default=None,
        description="Rebuild documents by joining rows that share this column, one row per line.",
    )
    order_by: str | None = Field(default=None, description="Row order within a group_by document.")
    local_path: str | None = Field(default=None, description="Path for non-HF sources.")

    modality: Modality
    text_column: str | None = Field(
        default=None, description="Column holding target-language text."
    )
    source_column: str | None = Field(
        default=None, description="Parallel sources: column holding the other language."
    )

    language: str = Field(description="BCP-47-ish tag, e.g. 'ak', 'ak-akuapem', 'en'.")
    claimed_variety: str | None = Field(
        default=None, description="Variety the source claims, verbatim from its card."
    )
    variety_audited: bool = Field(
        default=False,
        description="True only once a documented variety audit supports the label.",
    )

    provenance: Provenance
    licence: str = Field(description="SPDX-ish licence string from the dataset card.")
    licence_url: str | None = None
    commercial_use: bool = Field(
        default=False, description="False for any NC licence; gates checkpoint release."
    )

    role: Role
    normalization_rules: list[str] | None = Field(
        default=None, description="Rule names from akanlm.corpora.normalize; None = default."
    )

    expected_rows: int | None = Field(
        default=None, description="Row count from the card, checked at download time."
    )
    notes: str = ""

    @field_validator("hf_revision", "hf_parquet_revision")
    @classmethod
    def _revision_shape(cls, value: str | None) -> str | None:
        if value is None:
            return value
        if not (len(value) >= 7 and all(c in "0123456789abcdef" for c in value.lower())):
            raise ValueError(f"revision must be a hex commit SHA, got {value!r}")
        return value

    def model_post_init(self, __context) -> None:
        if self.hf_id is None and self.local_path is None:
            raise ValueError(f"source {self.name!r}: one of hf_id or local_path is required")
        if self.modality is Modality.PARALLEL and not self.source_column:
            raise ValueError(f"source {self.name!r}: parallel sources need source_column")
        if self.modality is Modality.MONOLINGUAL and not self.text_column:
            raise ValueError(f"source {self.name!r}: monolingual sources need text_column")
        if self.hf_files is not None:
            wanted = {self.text_column, self.source_column, self.group_by, self.order_by} - {None}
            if not self.hf_id or not self.hf_columns or not wanted <= set(self.hf_columns):
                raise ValueError(f"source {self.name!r}: hf_files needs hf_id and hf_columns "
                                 f"covering {sorted(wanted)}")
        if (self.group_by is None) != (self.order_by is None):
            raise ValueError(f"source {self.name!r}: group_by and order_by are declared together")
        if self.group_by and (self.hf_files is None or self.modality is not Modality.MONOLINGUAL):
            raise ValueError(f"source {self.name!r}: group_by applies to extracted monolingual sources")

    @property
    def is_trainable(self) -> bool:
        """Whether this source may appear in a pretraining mixture."""
        return self.role is Role.TRAIN

    def effective_rules(self) -> list[str]:
        from akanlm.corpora.normalize import rules_for_language

        return list(self.normalization_rules if self.normalization_rules is not None
                    else rules_for_language(self.language))


def load_source(path: Path) -> CorpusSource:
    """Load and validate a single corpus YAML."""
    data = yaml.safe_load(path.read_text(encoding="utf-8"))
    return CorpusSource.model_validate(data)


def load_sources(config_dir: Path) -> dict[str, CorpusSource]:
    """Load every ``*.yaml`` in *config_dir*, keyed by source name."""
    sources: dict[str, CorpusSource] = {}
    for path in sorted(config_dir.glob("*.yaml")):
        source = load_source(path)
        if source.name in sources:
            raise ValueError(f"duplicate source name {source.name!r} in {path}")
        sources[source.name] = source
    return sources


def assert_trainable(sources: Iterable[CorpusSource]) -> None:
    """Raise if any source is not permitted in a training mixture.

    This is the interlock that keeps FLORES+, MAFAND and the Ghana-NLP
    professional translations out of pretraining.
    """
    blocked = [s.name for s in sources if not s.is_trainable]
    if blocked:
        raise ValueError(
            "these sources are not permitted in a training mixture "
            f"(role != train): {', '.join(sorted(blocked))}"
        )


def unlicensed_for_release(sources: Iterable[CorpusSource]) -> list[str]:
    """Names of sources whose licence blocks commercial checkpoint release."""
    return sorted(s.name for s in sources if not s.commercial_use)
